CREATE TABLE accounts(id VARCHAR2(36) PRIMARY KEY,email VARCHAR2(254) NOT NULL UNIQUE,password_hash VARCHAR2(100) NOT NULL,verified NUMBER(1) DEFAULT 0 NOT NULL,preferences CLOB,created_at TIMESTAMP WITH TIME ZONE NOT NULL,version NUMBER(19) DEFAULT 0 NOT NULL);
CREATE TABLE auth_codes(id VARCHAR2(36) PRIMARY KEY,account_id VARCHAR2(36) NOT NULL REFERENCES accounts(id),kind VARCHAR2(10) NOT NULL CHECK(kind IN ('VERIFY','RESET')),code_hash VARCHAR2(64) NOT NULL,expires_at TIMESTAMP WITH TIME ZONE NOT NULL,UNIQUE(account_id,kind));
CREATE TABLE refresh_tokens(token_hash VARCHAR2(64) PRIMARY KEY,account_id VARCHAR2(36) NOT NULL REFERENCES accounts(id),expires_at TIMESTAMP WITH TIME ZONE NOT NULL,revoked NUMBER(1) DEFAULT 0 NOT NULL);
CREATE INDEX refresh_account ON refresh_tokens(account_id);
CREATE TABLE mail_delivery(id VARCHAR2(36) PRIMARY KEY,recipient VARCHAR2(254) NOT NULL,kind VARCHAR2(10) NOT NULL,secret_value VARCHAR2(128) NOT NULL,expires_at TIMESTAMP WITH TIME ZONE NOT NULL,attempts NUMBER(3) DEFAULT 0 NOT NULL,sent NUMBER(1) DEFAULT 0 NOT NULL);
